css:
.ll { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 12px; }
.ll-a { display: flex; flex-direction: column; gap: 4px; padding: 16px 18px; border-radius: 10px; border: 1px solid rgba(255,255,255,0.1); text-decoration: none; transition: border-color .25s ease, background .25s ease; }
.ll-a:hover { border-color: #00cdfd; background: rgba(0,205,253,0.06); }
.ll-t { font-family: var(--font-heading); font-weight: 600; font-size: 16px; letter-spacing: 0.04em; text-transform: uppercase; color: #f4fbff; }
.ll-d { font-size: 14px; font-weight: 300; line-height: 1.5; color: #9fb4c6; }
